from vlb_traj import Session
import numpy as np
s=Session(); s.record_start()
st=s.state(); p=np.array(st['entities']['pear']['get_grasped_keypoints'][0],float)
q0=np.array(st['robot']['tcp_quaternion_wxyz'],float); qd=np.array([0,.70710678,-.70710678,0.])
def ik(pos,q):
 r=s.ik(np.asarray(pos).tolist(),np.asarray(q).tolist())
 if not r['success']: raise RuntimeError('IK fail '+str(pos))
 return np.asarray(r['joint_positions'],float)
def hold(j,n,g=.04):
 for _ in range(n): s.step(np.r_[j,g,g])
def ramp(a,b,qa,qb,n,hn):
 for t in np.linspace(0,1,n):
  q=(1-t)*qa+t*qb; q=q/np.linalg.norm(q)
  hold(ik((1-t)*a+t*b,q),hn)
start=np.array(st['robot']['tcp_position'],float)
p1=start+[0,0,.12]; p2=np.array([p[0]+.15,p[1],1.10]); p3=np.array([p[0]+.12,p[1],.98]); p4=np.array([p[0]+.07,p[1],.92]); p5=np.array([p[0]+.025,p[1],.91])
try:
 ramp(start,p1,q0,q0,8,20); ramp(p1,p2,q0,qd,16,25); ramp(p2,p3,qd,qd,8,30); ramp(p3,p4,qd,qd,8,30); ramp(p4,p5,qd,qd,8,40)
 j=ik(p5,qd); hold(j,80,.04)
 for g in np.linspace(.04,0,12): hold(j,5,g)
except RuntimeError as e:
 print('STOPPED:',e)
print('STATUS',s.status())
st=s.state(); print('PEAR',st['entities']['pear']['position'],'TCP',st['robot']['tcp_position'],'FINGERS',st['robot']['gripper_positions'])
a=s.record_stop(); print('ACTIONS',a.shape)
s.save_trajectory(a,'/app/output/trajectory.npz')
